-- gorge_probe8: READ-ONLY. Trees standing inside the gorge's opening or on its rock: any tree in SouthGorge.Trees whose
-- base is closer to the river's centre than the rim + 2 (walls), or inside the headwall's radius + 2 (the cirque).
local Z_START, Z_END, DZS = -228.0, -548.0, 2.0
local CX = {174.50,175.69,176.88,178.25,179.62,181.00,182.38,183.62,184.88,186.00,187.12,188.25,189.38,190.31,191.25,191.81,192.38,192.62,192.88,192.88,192.88,192.56,192.25,191.50,190.75,189.69,188.62,187.44,186.25,184.69,183.12,181.25,179.38,177.81,176.25,174.88,173.50,171.50,169.50,166.88,164.25,161.75,159.25,157.06,154.88,152.69,150.50,148.31,146.12,144.12,142.12,140.31,138.50,136.81,135.12,133.56,132.00,130.44,128.88,127.12,125.37,123.62,121.87,120.37,118.87,117.56,116.21,115.10,113.88,112.79,111.74,110.89,110.34,110.10,110.01,110.00,110.00,110.00,110.00,110.00,110.00,110.03,110.11,110.34,110.81,111.64,112.77,114.39,116.05,117.72,119.19,120.55,121.87,123.50,125.12,127.00,128.87,130.75,132.62,134.56,136.50,138.50,140.50,142.50,144.50,146.56,148.62,150.75,152.88,154.94,157.00,159.06,161.12,163.31,165.50,167.69,169.88,171.94,174.00,175.88,177.75,179.38,181.00,182.44,183.88,185.31,186.75,188.25,189.75,191.19,192.62,194.06,195.50,196.69,197.88,198.50,199.12,199.56,200.00,200.38,200.75,200.75,200.75,200.25,199.75,198.94,198.12,197.31,196.50,195.62,194.75,193.69,192.62,191.56,190.50,189.50,188.50,187.38,186.25,184.88,183.50}
local RIMW = {13.08,13.35,13.67,13.50,13.28,13.41,14.08,15.57,16.17,16.00,17.17,16.86,17.70,19.94,19.31,20.93,21.34,20.72,21.26,21.33,20.84,21.38,21.90,23.85,22.46,23.21,24.65,26.44,26.22,26.13,25.99,25.69,26.85,26.23,25.87,25.29,24.77,24.89,26.21,26.79,26.88,27.00,27.35,27.49,26.09,25.41,24.97,24.69,25.26,23.83,23.67,23.73,24.09,22.62,22.68,24.48,24.18,24.35,26.23,26.15,26.15,25.06,25.17,25.97,24.82,25.91,27.59,29.57,31.65,35.07,38.13,38.50,38.01,38.52,38.86,39.15,39.29,39.36,39.33,39.58,39.16,38.88,38.52,38.27,37.71,36.86,35.78,34.06,32.06,30.69,27.06,24.72,22.68,20.82,19.52,19.42,17.82,17.76,17.88,17.83,17.99,19.38,19.48,19.06,19.33,19.92,20.07,21.71,21.67,22.14,22.15,22.10,22.43,22.69,23.22,24.27,23.01,22.85,22.99,23.33,23.71,24.27,24.88,25.55,23.59,23.54,23.61,23.78,23.96,24.29,26.21,25.83,25.78,25.53,25.30,25.18,25.03,26.18,25.85,25.63,25.62,26.19,24.07,24.08,24.44,22.47,23.18,23.60,23.66,23.80,23.87,23.73,23.68,25.59,25.21,25.16,25.15,24.04,23.86,23.81,23.72}
local RIME = {16.61,16.76,16.76,17.17,16.34,16.30,16.57,18.24,18.84,18.21,18.50,18.95,19.65,20.81,20.67,20.89,21.08,20.95,20.11,21.55,21.87,22.31,22.16,24.35,23.48,24.52,27.77,28.32,29.30,29.90,30.32,29.90,29.96,29.69,30.18,29.42,27.12,25.92,24.91,25.44,26.07,26.52,26.95,28.48,28.07,27.75,27.69,28.28,28.13,29.28,29.80,30.07,29.40,29.39,29.69,28.42,27.88,27.75,27.67,27.42,28.43,27.51,27.72,28.78,29.23,30.16,29.99,33.04,34.24,36.87,37.51,38.47,39.68,39.33,39.85,39.94,39.87,40.37,39.98,39.96,39.98,39.97,39.89,39.32,39.00,38.33,38.17,36.05,34.30,32.33,30.36,28.52,25.89,24.20,23.06,22.91,21.23,21.00,22.43,23.10,22.87,21.53,21.22,21.13,21.78,21.51,21.38,21.42,21.49,21.46,21.59,21.68,21.79,23.72,24.49,22.21,20.28,20.23,20.24,20.30,20.75,23.01,22.85,22.87,22.99,24.79,24.64,25.81,24.26,24.54,26.12,25.47,25.42,25.21,25.25,25.53,24.45,24.78,25.34,25.32,26.90,26.40,25.34,25.74,26.12,26.45,27.09,26.83,26.92,26.92,27.89,26.77,26.68,26.64,26.83,28.09,26.97,26.54,26.04,25.62,25.27}
local CXE, ZE, R, FW, FE = 183.84, -547.5, 15.28, 14.39, 17.44
local N = #CX
local function samp(a, z) local f = math.clamp((Z_START - z) / DZS + 1, 1, N); local i = math.min(math.floor(f), N - 1); local t = f - i; return a[i] * (1 - t) + a[i + 1] * t end
local function hwR(th) local w = math.sin(th) ^ 2; return ((th < math.pi / 2) and FW or FE) * (1 - w) + R * w end
local function aabb(m)
	local lo, hi = Vector3.new(math.huge, math.huge, math.huge), Vector3.new(-math.huge, -math.huge, -math.huge)
	for _, q in ipairs(m:GetDescendants()) do
		if q:IsA("BasePart") then
			local cf, s = q.CFrame, q.Size / 2
			local ext = Vector3.new(math.abs(cf.RightVector.X) * s.X + math.abs(cf.UpVector.X) * s.Y + math.abs(cf.LookVector.X) * s.Z,
				math.abs(cf.RightVector.Y) * s.X + math.abs(cf.UpVector.Y) * s.Y + math.abs(cf.LookVector.Y) * s.Z,
				math.abs(cf.RightVector.Z) * s.X + math.abs(cf.UpVector.Z) * s.Y + math.abs(cf.LookVector.Z) * s.Z)
			lo = lo:Min(cf.Position - ext); hi = hi:Max(cf.Position + ext)
		end
	end
	return lo, hi
end
local out = {}
for _, m in ipairs(workspace.SouthGorge.Trees:GetChildren()) do
	local lo, hi = aabb(m)
	local x, z = (lo.X + hi.X) / 2, (lo.Z + hi.Z) / 2
	local why
	if z <= Z_START and z >= Z_END then
		local c = samp(CX, z); local d = math.abs(x - c); local rim = samp(x >= c and RIME or RIMW, z)
		if d < rim + 2.0 then why = string.format("wall d%.1f rim%.1f", d, rim) end
	elseif z < Z_END then
		local rr = math.sqrt((x - CXE) ^ 2 + (z - ZE) ^ 2); local th = math.clamp(math.atan2(-(z - ZE), -(x - CXE)), 0, math.pi)
		local lim = hwR(th) + 0.22 * math.max(lo.Y, 0) + 1.4 + 2.0
		if rr < lim then why = string.format("cirque rr%.1f lim%.1f", rr, lim) end
	end
	if why then out[#out + 1] = string.format("%s@%.0f,%.1f,%.0f (%s)", m.Name, x, lo.Y, z, why) end
end
print("QQ G8 trees in the gorge: " .. #out .. " | " .. table.concat(out, " "))
print("QQ G8 DONE")
